export default async function f({ data, previous, acknowledge, resolution }, ctx) {
  let s = previous;
  if (!s) {
    if (!Array.isArray(data.cards) || !data.cards.length)
      throw Error("Newsroom card selector returned no cards");
    const cutoff = Date.now() - 70 * 86400000,
      items = [];
    let prior = Infinity;
    for (const x of data.cards) {
      const t = Date.parse(x.date);
      if (!Number.isFinite(t) || t > prior || !x.link || !x.title)
        throw Error("Newsroom cards changed or dates are unordered");
      prior = t;
      const u = new URL(x.link, "https://www.colt.net");
      if (u.origin !== "https://www.colt.net" || !u.pathname.startsWith("/resources/insights/"))
        throw Error("Unexpected article URL");
      if (t >= cutoff && t <= Date.now())
        items.push({
          date: new Date(t).toISOString().slice(0, 10),
          url: u.href,
          title: x.title.trim(),
        });
    }
    if (prior >= cutoff) throw Error("Newsroom listing does not cover the full 70-day window");
    s = { items, index: 0 };
  }
  for (let i = s.index; i < s.items.length; i++) {
    const item = s.items[i],
      key = "colt-news:" + item.url,
      v = await ctx.state.get(key);
    if (v?.status === "done") continue;
    if (v?.status === "pending") {
      if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
        throw Error("Inspect pending NocoDB record");
      if (resolution === "confirmed") {
        await ctx.state.set(key, { status: "done" });
        continue;
      }
    }
    return { state: { ...s, index: i + 1 }, more: true, item, key, url: item.url };
  }
  return {
    state: { ...s, index: s.items.length },
    more: false,
    item: {},
    key: "",
    url: "https://www.colt.net/",
  };
}

