export default async function f({ summary, keywords, item, key }, ctx) {
  if (!summary || !keywords || !item.url || !item.title)
    throw Error("Missing summary, keywords or article identity");
  await ctx.state.set(key, { status: "pending", url: item.url });
  return {
    rows: [
      {
        News_Source: "Colt",
        Title: item.title,
        Date: item.date,
        Link: item.url,
        Summary: summary,
        Keywords: keywords,
      },
    ],
  };
}

